     1→/**
     2→ * Image Generation API Route
     3→ * POST /api/generate-image
     4→ *
     5→ * Handles outfit image generation requests using OpenRouter's Gemini 2.5 Flash Preview model
     6→ *
     7→ * Features:
     8→ * - Server-side rate limiting (10 requests per minute per IP)
     9→ * - Request validation
    10→ * - Error handling with appropriate HTTP status codes
    11→ * - Logging for debugging
    12→ */
    13→
    14→import { NextRequest, NextResponse } from 'next/server';
    15→import { OpenRouterImageClient } from '@/lib/services/image-generation-service';
    16→import type { ImageGenerationRequest } from '@/lib/types/image-types';
    17→import fs from 'fs';
    18→import path from 'path';
    19→
    20→/**
    21→ * Rate limiting configuration
    22→ * Tracks request counts per IP address
    23→ */
    24→const rateLimitMap = new Map<string, { count: number; resetTime: number }>();
    25→const RATE_LIMIT_WINDOW = 60000; // 1 minute in milliseconds
    26→const RATE_LIMIT_MAX_REQUESTS = 10;
    27→
    28→/**
    29→ * Checks if request is rate limited
    30→ *
    31→ * @param ip - Client IP address
    32→ * @returns true if rate limited, false if allowed
    33→ */
    34→function isRateLimited(ip: string): boolean {
    35→  const now = Date.now();
    36→  const record = rateLimitMap.get(ip);
    37→
    38→  // No record or window expired - create new record
    39→  if (!record || now > record.resetTime) {
    40→    rateLimitMap.set(ip, {
    41→      count: 1,
    42→      resetTime: now + RATE_LIMIT_WINDOW,
    43→    });
    44→    return false;
    45→  }
    46→
    47→  // Increment count
    48→  record.count++;
    49→
    50→  // Check if over limit
    51→  if (record.count > RATE_LIMIT_MAX_REQUESTS) {
    52→    return true;
    53→  }
    54→
    55→  return false;
    56→}
    57→
    58→/**
    59→ * Gets client IP address from request
    60→ *
    61→ * @param request - Next.js request object
    62→ * @returns IP address string
    63→ */
    64→function getClientIP(request: NextRequest): string {
    65→  // Try various headers that might contain the real IP
    66→  const forwarded = request.headers.get('x-forwarded-for');
    67→  if (forwarded) {
    68→    return forwarded.split(',')[0].trim();
    69→  }
    70→
    71→  const realIP = request.headers.get('x-real-ip');
    72→  if (realIP) {
    73→    return realIP;
    74→  }
    75→
    76→  // Fallback to a default value
    77→  return 'unknown';
    78→}
    79→
    80→/**
    81→ * Ensures a directory exists, creating it if necessary
    82→ *
    83→ * @param dirPath - Absolute path to the directory
    84→ */
    85→function ensureDirectoryExists(dirPath: string): void {
    86→  if (!fs.existsSync(dirPath)) {
    87→    fs.mkdirSync(dirPath, { recursive: true });
    88→    console.log('[API] Created directory:', dirPath);
    89→  }
    90→}
    91→
    92→/**
    93→ * Generates a unique filename for an outfit image
    94→ *
    95→ * @returns Filename in format: outfit-{timestamp}.png
    96→ */
    97→function generateImageFilename(): string {
    98→  const timestamp = Date.now();
    99→  return `outfit-${timestamp}.png`;
   100→}
   101→
   102→/**
   103→ * Saves a base64-encoded image to disk as a PNG file
   104→ *
   105→ * @param base64Data - Base64 image data (with or without data URL prefix)
   106→ * @param filename - Name of the file to save
   107→ * @returns Relative public URL path to the saved image
   108→ * @throws Error if file save fails
   109→ */
   110→function saveBase64Image(base64Data: string, filename: string): string {
   111→  // Strip data URL prefix if present (e.g., "data:image/png;base64,")
   112→  const base64Content = base64Data.includes(',')
   113→    ? base64Data.split(',')[1]
   114→    : base64Data;
   115→
   116→  // Construct absolute path to the public/generated-images directory
   117→  const publicDir = path.join(process.cwd(), 'public', 'generated-images');
   118→  ensureDirectoryExists(publicDir);
   119→
   120→  const filePath = path.join(publicDir, filename);
   121→
   122→  // Convert base64 to buffer and write to file
   123→  const imageBuffer = Buffer.from(base64Content, 'base64');
   124→  fs.writeFileSync(filePath, imageBuffer);
   125→
   126→  console.log('[API] Saved image to:', filePath);
   127→
   128→  // Return public URL path (relative)
   129→  return `/generated-images/${filename}`;
   130→}
   131→
   132→/**
   133→ * POST handler for image generation
   134→ *
   135→ * Request body:
   136→ * {
   137→ *   description: string,
   138→ *   style?: {
   139→ *     photographyStyle?: string,
   140→ *     composition?: string,
   141→ *     lighting?: string,
   142→ *     aestheticContext?: string
   143→ *   }
   144→ * }
   145→ *
   146→ * Response on success:
   147→ * {
   148→ *   success: true,
   149→ *   imageUrl: string,        // Public URL path (e.g., /generated-images/outfit-1732800000000.png)
   150→ *   imageBase64: string,      // Base64-encoded image data
   151→ *   error?: undefined,
   152→ *   message?: undefined
   153→ * }
   154→ *
   155→ * Response on failure:
   156→ * {
   157→ *   success: false,
   158→ *   imageUrl?: undefined,
   159→ *   imageBase64?: undefined,
   160→ *   error: string,
   161→ *   message: string
   162→ * }
   163→ */
   164→export async function POST(request: NextRequest) {
   165→  const startTime = Date.now();
   166→
   167→  try {
   168→    // Get client IP for rate limiting
   169→    const clientIP = getClientIP(request);
   170→
   171→    console.log('[API] Image generation request received from IP:', clientIP);
   172→
   173→    // Check rate limiting
   174→    if (isRateLimited(clientIP)) {
   175→      console.warn('[API] Rate limit exceeded for IP:', clientIP);
   176→      return NextResponse.json(
   177→        {
   178→          success: false,
   179→          error: 'RATE_LIMITED',
   180→          message: 'Too many requests. Please wait a minute before trying again.',
   181→        },
   182→        {
   183→          status: 429,
   184→          headers: {
   185→            'Retry-After': '60',
   186→          },
   187→        }
   188→      );
   189→    }
   190→
   191→    // Check if OPENROUTER_API_KEY is configured
   192→    const apiKey = process.env.OPENROUTER_API_KEY;
   193→    if (!apiKey) {
   194→      console.error('[API] OPENROUTER_API_KEY not configured');
   195→      return NextResponse.json(
   196→        {
   197→          success: false,
   198→          error: 'SERVICE_UNAVAILABLE',
   199→          message: 'ขออภัยค่ะ ระบบสร้างภาพยังไม่พร้อมใช้งานในขณะนี้ กรุณาลองใหม่ภายหลังนะคะ',
   200→        },
   201→        { status: 503 }
   202→      );
   203→    }
   204→
   205→    // Parse request body
   206→    let body: ImageGenerationRequest;
   207→    try {
   208→      body = await request.json();
   209→    } catch (error) {
   210→      console.error('[API] Invalid JSON in request body:', error);
   211→      return NextResponse.json(
   212→        {
   213→          success: false,
   214→          error: 'INVALID_REQUEST',
   215→          message: 'Invalid request format',
   216→        },
   217→        { status: 400 }
   218→      );
   219→    }
   220→
   221→    // Validate request body
   222→    const { description, style, referenceImage, generationType } = body;
   223→
   224→    if (!description || typeof description !== 'string' || description.trim() === '') {
   225→      console.error('[API] Missing or invalid description');
   226→      return NextResponse.json(
   227→        {
   228→          success: false,
   229→          error: 'INVALID_DESCRIPTION',
   230→          message: 'Outfit description is required',
   231→        },
   232→        { status: 400 }
   233→      );
   234→    }
   235→
   236→    // Validate description length (3000 chars for fitting-model, 1000 for outfit)
   237→    const maxDescriptionLength = generationType === 'fitting-model' ? 3000 : 1000;
   238→    if (description.length > maxDescriptionLength) {
   239→      console.error('[API] Description too long:', description.length);
   240→      return NextResponse.json(
   241→        {
   242→          success: false,
   243→          error: 'DESCRIPTION_TOO_LONG',
   244→          message: `Description is too long. Please keep it under ${maxDescriptionLength} characters.`,
   245→        },
   246→        { status: 400 }
   247→      );
   248→    }
   249→
   250→    // Validate referenceImage when generationType is 'fitting-model'
   251→    if (generationType === 'fitting-model') {
   252→      if (!referenceImage || typeof referenceImage !== 'string' || referenceImage.trim() === '') {
   253→        console.error('[API] Missing reference image for fitting-model generation');
   254→        return NextResponse.json(
   255→          {
   256→            success: false,
